\newcommand{\choices}[4]{%
  \par\vspace{0.15em}
  \begin{tabularx}{\linewidth}{@{}X@{\hspace{1em}}X@{}}
    \textup{(A)}\,#1 & \textup{(B)}\,#2 \\
